/* gw-meta-events - EXTERNAL build. Generated by scripts/builderall_meta_events.py
   build_block(). Lives here because the Builderall Custom Head Markup is capped at
   20,000 chars and the inline version pushed it to ~21,115, so Builderall silently
   truncated it mid-statement (measured 2026-08-19). DO NOT hand-edit: regenerate. */
/* gw-meta-events: browser-side Meta events for pixel 1479621642070304.
   Lead shares its event_id with the server-side CAPI call (keap-worker metaCapiLead)
   so Meta counts ONE conversion, not two. Contact = tel: tap. ViewContent = LOB page.
   FormStart = first field focus. All queued until the deferred pixel finishes loading.
   Revert = restore the backup in output/website-cutover/backups/. */
(function(){
if(window.__gwMetaEvents)return; window.__gwMetaEvents=1;
var Q=[],flushing=false,tries=0;
function flush(){if(!window.fbq)return false;while(Q.length){try{window.fbq.apply(null,Q.shift());}catch(e){}}return true;}
function arm(){if(flushing)return;flushing=true;var t=setInterval(function(){
  tries++; if(flush()||tries>80){clearInterval(t);flushing=false;}},250);}
function gwFbq(){if(window.fbq){try{window.fbq.apply(null,arguments);}catch(e){}return;}
  Q.push(Array.prototype.slice.call(arguments)); arm();}
function uuid(){try{if(crypto&&crypto.randomUUID)return crypto.randomUUID();}catch(e){}
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g,function(c){
    var r=Math.random()*16|0,v=c=='x'?r:(r&0x3|0x8);return v.toString(16);});}

/* ---- Lead: wrap fetch so the SAME id reaches the Worker and the pixel ---- */
var OF=window.fetch;
if(typeof OF==='function'){window.fetch=function(input,init){
  var url='';try{url=(typeof input==='string')?input:((input&&input.url)||'');}catch(e){}
  var eid=null;
  try{
    if(init&&init.method&&String(init.method).toUpperCase()==='POST'&&url.indexOf('goodwill-keap-followup')>-1&&typeof init.body==='string'){
      var d=JSON.parse(init.body);
      if(d&&d.kind==='website'&&!d.company_website&&!d['company-website']){
        eid=uuid(); d.eventId=eid;
        var ni={};for(var k in init){if(Object.prototype.hasOwnProperty.call(init,k))ni[k]=init[k];}
        ni.body=JSON.stringify(d); init=ni;
      }
    }
  }catch(e){}
  var p=OF.call(this,input,init);
  if(eid){try{p.then(function(r){if(r&&r.ok){
    gwFbq('track','Lead',{content_category:(location.pathname||'/')},{eventID:eid});}
  }).catch(function(){});}catch(e){}}
  return p;};}

/* ---- Contact: tap-to-call (STANDARD event, optimisable) ---- */
document.addEventListener('click',function(e){
  var t=e.target; if(!t||!t.closest)return; var a=t.closest('a[href^="tel:"]'); if(!a)return;
  gwFbq('track','Contact',{content_category:'phone'});},true);

/* ---- FormStart: first field focus, once per pageview ---- */
var started=false;
document.addEventListener('focusin',function(e){
  if(started)return; var t=e.target; if(!t||!t.tagName)return;
  if(!/^(INPUT|TEXTAREA|SELECT)$/.test(t.tagName))return;
  if(/^(hidden|submit|button)$/i.test(t.type||''))return;
  if(!t.closest||!t.closest('form'))return;
  started=true; gwFbq('trackCustom','FormStart',{content_category:(location.pathname||'/')});},true);

/* ---- ViewContent: line-of-business pages only ---- */
var LOB=['auto-insurance','homeowners','renters','landlord','umbrella','flood','motorcycle-watercraft','personal-insurance','commercial-insurance','commercial-auto','commercial-property','business-owners-policy','general-liability','workers-compensation','cyber','truck-insurance','life-insurance','term-life','living-benefits','mortgage-protection','annuities','tax-free-retirement','what-is-iul','sba-lenders'];
var pth=(location.pathname||'').toLowerCase();
for(var i=0;i<LOB.length;i++){if(pth.indexOf(LOB[i])>-1){
  gwFbq('track','ViewContent',{content_category:LOB[i]}); break;}}
})();